// Core scalar keywords: type, enum, const.
// Error objects are { path, schemaPath } with paths RELATIVE to the current
// location; the engine prepends the current instance/schema paths.

import { makeError } from "../errors.mjs";

function isPlainObject(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

// Deep equality matching jsonschema's enum/const semantics (verified against
// the reference executable):
//   - numbers compare by value: 1 == 1.0 (also nested: {a: 1} == {a: 1.0})
//   - booleans are NEVER equal to numbers, at any nesting depth:
//     true != 1, false != 0, [1, 1] != [1, true]
//   - arrays compare element-wise, objects key-wise (order-insensitive)
export function pyEqual(a, b) {
  if (typeof a === "boolean" || typeof b === "boolean") return a === b;
  if (a === null || b === null) return a === b;
  if (typeof a === "number" && typeof b === "number") return a === b;
  if (typeof a === "string" && typeof b === "string") return a === b;
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!pyEqual(a[i], b[i])) return false;
    }
    return true;
  }
  if (isPlainObject(a) && isPlainObject(b)) {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    for (const key of keysA) {
      if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
      if (!pyEqual(a[key], b[key])) return false;
    }
    return true;
  }
  return false;
}

const TYPE_CHECKS = {
  null: (instance) => instance === null,
  boolean: (instance) => typeof instance === "boolean",
  string: (instance) => typeof instance === "string",
  // Booleans are not numbers: typeof true === "boolean", so this excludes them.
  number: (instance) => typeof instance === "number",
  // JS cannot distinguish 5 from 5.0 after JSON.parse, so "integer" accepts
  // any number with an integral value (draft6+ semantics; see report note).
  integer: (instance) =>
    typeof instance === "number" && Number.isInteger(instance),
  object: (instance) => isPlainObject(instance),
  array: (instance) => Array.isArray(instance),
};

function type(ctx, value, instance /*, schema */) {
  const types = Array.isArray(value) ? value : [value];
  // Evaluate every member eagerly: the reference crashes with UnknownType
  // even when an earlier member would have matched (e.g. ["string", 5]).
  let matched = false;
  for (const t of types) {
    const check = TYPE_CHECKS[t];
    if (check === undefined) {
      throw new Error(`Unknown type ${JSON.stringify(t)}`);
    }
    if (check(instance)) matched = true;
  }
  return matched ? [] : [makeError()];
}

function enum_(ctx, value, instance /*, schema */) {
  if (!Array.isArray(value)) return [];
  for (const each of value) {
    if (pyEqual(instance, each)) return [];
  }
  return [makeError()];
}

function const_(ctx, value, instance /*, schema */) {
  return pyEqual(instance, value) ? [] : [makeError()];
}

export const keywords = {
  type,
  enum: enum_,
  const: const_,
};

// Numeric keywords: minimum, maximum, exclusiveMinimum, exclusiveMaximum,
// multipleOf. All apply to numbers only (booleans excluded via typeof).
//
// exclusiveMinimum/exclusiveMaximum are draft-aware:
//   - draft 4: boolean modifiers of minimum/maximum (no standalone validator)
//   - draft 6+: numeric keywords compared against the instance

import { makeError } from "../errors.mjs";

function isNumber(value) {
  return typeof value === "number";
}

function minimum(ctx, value, instance, schema) {
  if (!isNumber(instance) || !isNumber(value)) return [];
  if (ctx.draft === 4 && schema.exclusiveMinimum) {
    return instance <= value ? [makeError()] : [];
  }
  return instance < value ? [makeError()] : [];
}

function maximum(ctx, value, instance, schema) {
  if (!isNumber(instance) || !isNumber(value)) return [];
  if (ctx.draft === 4 && schema.exclusiveMaximum) {
    return instance >= value ? [makeError()] : [];
  }
  return instance > value ? [makeError()] : [];
}

function exclusiveMinimum(ctx, value, instance /*, schema */) {
  if (ctx.draft === 4) return []; // boolean modifier of minimum in draft 4
  if (!isNumber(instance) || !isNumber(value)) return [];
  return instance <= value ? [makeError()] : [];
}

function exclusiveMaximum(ctx, value, instance /*, schema */) {
  if (ctx.draft === 4) return []; // boolean modifier of maximum in draft 4
  if (!isNumber(instance) || !isNumber(value)) return [];
  return instance >= value ? [makeError()] : [];
}

function multipleOf(ctx, value, instance /*, schema */) {
  if (!isNumber(instance) || !isNumber(value)) return [];
  let failed;
  if (Number.isInteger(value)) {
    failed = instance % value !== 0;
  } else {
    // Python semantics: quotient = instance / divisor;
    // fails when int(quotient) != quotient.
    const quotient = instance / value;
    failed = Math.trunc(quotient) !== quotient;
  }
  return failed ? [makeError()] : [];
}

export const keywords = {
  minimum,
  maximum,
  exclusiveMinimum,
  exclusiveMaximum,
  multipleOf,
};

// String keywords: minLength, maxLength, pattern. Apply to strings only.
// String length is measured in Unicode code points, matching Python len().

import { makeError } from "../errors.mjs";

function minLength(ctx, value, instance /*, schema */) {
  if (typeof instance !== "string" || typeof value !== "number") return [];
  return [...instance].length < value ? [makeError()] : [];
}

function maxLength(ctx, value, instance /*, schema */) {
  if (typeof instance !== "string" || typeof value !== "number") return [];
  return [...instance].length > value ? [makeError()] : [];
}

function pattern(ctx, value, instance /*, schema */) {
  if (typeof instance !== "string" || typeof value !== "string") return [];
  // Approximate Python re.search with an unanchored JS RegExp test.
  // The "u" flag makes "." and character classes code-point based, closer
  // to Python's Unicode semantics. Invalid patterns throw, like Python's
  // re.error crash.
  const re = new RegExp(value, "u");
  return re.test(instance) ? [] : [makeError()];
}

export const keywords = {
  minLength,
  maxLength,
  pattern,
};

